module case70(
    input logic [1:0] op,
    input logic [3:0] a, b,
    output logic [7:0] result
);
    always_comb begin
        case(op)
            2'b00: result = a + b;
            2'b01: result = a - b;
            2'b10: result = a * b;
            2'b11: result = a / (b != 0 ? b : 1);
        endcase
    end
endmodule,"module case70_assertions(

module nested_case_1(input logic [1:0] op, func, input logic [7:0] a,b, output logic [7:0] y);
always_comb begin
  case(op)
    2'b00: begin
      case(func)
        2'b00: y = a + b;
        2'b01: y = a - b;
        default: y = 0;
      endcase
    end
    2'b01: y = a & b;
    default: y = 8'h00;
  endcase
end
endmodule,"nested_case_1_assertions(input logic [1:0] op, func, input logic [7:0] a, b, output logic [7:0] y)

module nested_case_2(input logic [2:0] mode, sel, output logic [3:0] y);
always_comb begin
  case(mode)
    3'b000: begin
      case(sel)
        3'b000: y = 1;
        3'b001: y = 2;
        default: y = 0;
      endcase
    end
    3'b001: y = 4;
    default: y = 0;
  endcase
end
endmodule,"module nested_case_2_assertions(input logic [2:0] mode, sel, output logic [3:0] y)

module nested_case_3(input logic [1:0] a,b,c, output logic y);
always_comb begin
  case(a)
    2'b00: begin
      case(b)
        2'b00: y = c[0];
        2'b01: y = c[1];
        default: y = 0;
      endcase
    end
    default: y = 1;
  endcase
end
endmodule,"module nested_case_3_assertions(input logic [1:0] a, b, c, output logic y)

module nested_case_27(input logic [1:0] sel_a, sel_b, output logic [3:0] out);
always_comb begin
  case(sel_a)
    2'b0x: begin
      case(sel_b)
        2'b0z: out = 4'b0001;
        2'bz1: out = 4'b0010;
        2'bxx: out = 4'b0100;  // All x's
        default: out = 4'b0000;
      endcase
    end
    2'bz0: out = 4'b1000;
    2'b1x: out = 4'b1100;
    default: out = 4'b0000;
  endcase
end
endmodule,"module nested_case_27_assertions(input logic [1:0] sel_a, sel_b, output logic [3:0] out)

module nested_case_31(input logic [1:0] mode, input logic enable, output logic [2:0] led);
always_comb begin
  case(mode)
    2'b00: begin
      case(enable)
        1'b1: led = 3'b111;
        1'b0: led = 3'b000;
        default: led = 3'b000;
      endcase
    end
    2'b01: led = 3'b001;
    default: led = 3'b000;
  endcase
end
endmodule,"module nested_case_31_assertions(

